// FREQUENCY comes from the F slider (Constants dock): raise F for finer
// stripes, lower it for wider ones. F = 1 is the width this preset has
// always had. max() keeps the stripes from vanishing if F is left at 0.
float FREQ = 10.0 * max(F, 0.05);   // slider F

// Compute how much each axis (X, Y, Z) weighs based on the normal
vec3 blend = abs(n_model);
blend /= max(blend.x + blend.y + blend.z, 0.00001);

// Generate different procedural patterns for each projection plane
vec3 colX = vec3(sin(pModel.y * FREQ) * 0.5 + 0.5, 0.0, 0.0); // Red stripes on the YZ plane
vec3 colY = vec3(0.0, sin(pModel.x * FREQ) * 0.5 + 0.5, 0.0); // Green stripes on the XZ plane
vec3 colZ = vec3(0.0, 0.0, sin(pModel.x * FREQ) * 0.5 + 0.5); // Blue stripes on the XY plane

// Blend the patterns using the normal weights
textureCol = colX * blend.x + colY * blend.y + colZ * blend.z;
